use mdbook_language_lab::process;
use serde_json::{Value, json};

fn chapter(path: &str, content: &str) -> Value {
    json!({"Chapter": {"path": path, "content": content, "sub_items": []}})
}
fn render(source: &str) -> String {
    let mut book = json!({"items": [chapter("test.md", source)]});
    process(&mut book).unwrap();
    book["items"][0]["Chapter"]["content"]
        .as_str()
        .unwrap()
        .into()
}

pub fn valid_id(s: &str) -> bool {
    !s.is_empty()
        && s.bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b".-_".contains(&b))
}

chapters(items, &mut |ch| {
    let source = ch["content"].as_str().ok_or("missing chapter content")?;
    for role in roles(source).into_iter().filter(|r| r.name == "req") {
        let path = ch["path"]
            .as_str()
            .ok_or("requirement in chapter without output path")?;
        if !valid_id(&role.label) || !role.label.contains('.') {
            return Err(format!(
                "{path}: invalid requirement identifier {:?}",
                role.label
            ));
        }
        if let Some(previous) = definitions.insert(role.label.clone(), path.to_owned()) {
            return Err(format!(
                "{path}: duplicate requirement {} (first defined in {previous})",
                role.label
            ));
        }
    }
    Ok(())
})?;

#[test]
fn identifier_alphabet_and_required_dot() {
    for id in ["a.b", "0.9", "a-b.c_d", ".", "a..b"] {
        let output = render(&format!("{{req}}`{id}` Text."));
        assert!(output.contains(&format!("id=\"req-{id}\"")));
    }
    for id in ["nodot", "A.b", "é.b", "a b", "a/b", "a:b", "a<b", "a\\b"] {
        let mut book = json!({"items": [chapter("invalid.md", &format!("{{req}}`{id}` Text."))]});
        let error = process(&mut book).unwrap_err();
        assert!(
            error.contains("invalid requirement identifier"),
            "{id}: {error}"
        );
        assert!(error.contains("invalid.md"));
    }
}

use serde_json::{Value, json};
use std::io::Write;
use std::process::{Command, Stdio};

fn execute(input: &Value) -> std::process::Output {
    let mut child = Command::new(env!("CARGO_BIN_EXE_mdbook-language-lab"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    child
        .stdin
        .take()
        .unwrap()
        .write_all(input.to_string().as_bytes())
        .unwrap();
    child.wait_with_output().unwrap()
}

#[test]
fn semantic_and_protocol_errors_never_publish_partial_books() {
    let cases = [
        (
            json!([{"renderer":"html"},{"items":[
                {"Chapter":{"path":"one.md","content":"{req}`a.b` Rule.","sub_items":[]}},
                {"Chapter":{"path":"two.md","content":"{req}`a.b` Duplicate.","sub_items":[]}}
            ]}]),
            vec!["duplicate", "a.b", "one.md", "two.md"],
        ),
        (
            json!([{"renderer":"html"},{"items":[
                {"Chapter":{"path":"one.md","content":"{req}`a.b` Rule.","sub_items":[]}},
                {"Chapter":{"path":"two.md","content":"{unknown.id}`Missing`", "sub_items":[]}}
            ]}]),
            vec!["unknown.id", "two.md"],
        ),
        (
            json!([{"renderer":"html"},{"items":[
                {"Chapter":{"path":"bad.md","content":"{req}`Invalid.id`", "sub_items":[]}}
            ]}]),
            vec!["invalid requirement", "bad.md"],
        ),
        (json!([{"renderer":"latex"},{"items":[]}]), vec!["html"]),
        (json!([{"renderer":"html"},{"items":{}}]), vec!["array"]),
    ];
    for (input, fragments) in cases {
        let output = execute(&input);
        assert!(!output.status.success());
        assert!(output.stdout.is_empty());
        let error = String::from_utf8(output.stderr).unwrap();
        for fragment in fragments {
            assert!(error.contains(fragment), "{error}");
        }
    }

    let input: Value = serde_json::from_reader(io::stdin()).map_err(|e| e.to_string())?;
    let pair = input
        .as_array()
        .filter(|p| p.len() == 2)
        .ok_or("expected [context, book]")?;
    if pair[0]["renderer"] != "html" {
        return Err("only the html renderer is supported".into());
    }
    let mut book = pair[1].clone();
    process(&mut book)?;
    serde_json::to_writer(io::stdout(), &book).map_err(|e| e.to_string())
}

fn main() {
    if let Err(error) = run() {
        eprintln!("mdbook-language-lab: {error}");
        std::process::exit(1);
    }
}
